package com.lims.model;
import java.sql.Timestamp; import java.util.ArrayList; import java.util.List;
public class ExportRequest { private int requestId,customerId,assignedTo; private String customerName,createdByName,assignedName,status,cancelReason,note; private Timestamp requestDate,approvedDate; private List<ExportRequestItem> items=new ArrayList<>(); public int getRequestId(){return requestId;} public void setRequestId(int v){requestId=v;} public int getCustomerId(){return customerId;} public void setCustomerId(int v){customerId=v;} public int getAssignedTo(){return assignedTo;} public void setAssignedTo(int v){assignedTo=v;} public String getCustomerName(){return customerName;} public void setCustomerName(String v){customerName=v;} public String getCreatedByName(){return createdByName;} public void setCreatedByName(String v){createdByName=v;} public String getAssignedName(){return assignedName;} public void setAssignedName(String v){assignedName=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getCancelReason(){return cancelReason;} public void setCancelReason(String v){cancelReason=v;} public String getNote(){return note;} public void setNote(String v){note=v;} public Timestamp getRequestDate(){return requestDate;} public void setRequestDate(Timestamp v){requestDate=v;} public Timestamp getApprovedDate(){return approvedDate;} public void setApprovedDate(Timestamp v){approvedDate=v;} public List<ExportRequestItem> getItems(){return items;} public void setItems(List<ExportRequestItem> v){items=v;} }
